import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import {
  GoogleMap,
  Marker,
  DirectionsRenderer,
  useJsApiLoader
} from "@react-google-maps/api";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const GOOGLE_MAPS_API_KEY = process.env.REACT_APP_GOOGLE_MAPS_API_KEY || "";

const containerStyle = { width: "100%", height: "600px" };
const defaultCenter = { lat: 6.9271, lng: 79.8612 };

export default function DeliveryTracking() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const mapRef = useRef<google.maps.Map | null>(null);

  const [driverLocation, setDriverLocation] = useState<google.maps.LatLngLiteral | null>(null);
  const [destination, setDestination] = useState<google.maps.LatLngLiteral | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);

  const { isLoaded } = useJsApiLoader({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
    libraries: ["places"]
  });

  // 1️⃣ Fetch delivery + driver, geocode driver address
  useEffect(() => {
    if (!id) return;
    (async () => {
      try {
        const { data: delivery } = await axios.get(`${API_BASE_URL}/api/delivery/${id}`);
        setDestination(delivery.location);

        const { data: driver } = await axios.get(
          `${API_BASE_URL}/api/drivers/${delivery.driverId}`
        );
        // geocode driver.address
        const { data: geo } = await axios.get(
          `https://maps.googleapis.com/maps/api/geocode/json`,
          {
            params: { address: driver.address, key: GOOGLE_MAPS_API_KEY }
          }
        );
        const loc = geo.results[0].geometry.location;
        setDriverLocation({ lat: loc.lat, lng: loc.lng });
      } catch (e) {
        console.error("Fetch error:", e);
      }
    })();
  }, [id]);

  // 2️⃣ Once we have both points, request and render the route
  useEffect(() => {
    if (!driverLocation || !destination || !isLoaded) return;

    const service = new google.maps.DirectionsService();
    service.route(
      {
        origin: driverLocation,
        destination,
        travelMode: google.maps.TravelMode.DRIVING
      },
      (result, status) => {
        console.log("Directions status:", status);
        console.log("Directions result:", result);
        if (status === "OK" && result) {
          setDirections(result);
          // auto-zoom to fit
          mapRef.current?.fitBounds(result.routes[0].bounds);
        }
      }
    );
  }, [driverLocation, destination, isLoaded]);

  if (!isLoaded) return <div>Loading map…</div>;

  return (
    <div style={{ padding: 20 }}>
      <button
        onClick={() => navigate(-1)}
        style={{
          marginBottom: 10,
          padding: "8px 16px",
          background: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: 4,
          cursor: "pointer"
        }}
      >
        ← Back
      </button>

      <GoogleMap
        mapContainerStyle={containerStyle}
        center={driverLocation || destination || defaultCenter}
        zoom={12}
        onLoad={map => { mapRef.current = map; }}
      >
        {driverLocation && <Marker position={driverLocation} label="🚚" />}
        {destination && <Marker position={destination} label="📍" />}

        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{
              suppressMarkers: true,
              polylineOptions: {
                strokeColor: "#1E90FF",
                strokeOpacity: 0.8,
                strokeWeight: 6
              }
            }}
          />
        )}
      </GoogleMap>
    </div>
  );
}
